/**
 * Real-server verification runner (temporary harness, not part of the plugin).
 *
 * Executes every SQL statement in cases.json (generated by gen.ts) against a
 * live KWDB through psql and records OK / FAIL / EMPTY plus row counts.
 *
 * Required environment variables (no defaults on purpose: this harness must
 * never silently connect to an internal instance):
 *   KWDB_HOST, KWDB_PORT, KWDB_DATABASE, KWDB_USER, KWDB_PASSWORD
 *
 * Usage:
 *   KWDB_HOST=db.example.com KWDB_PORT=26257 KWDB_DATABASE=example_db \
 *   KWDB_USER=readonly_user KWDB_PASSWORD=secret \
 *   npx ts-node --compiler-options '{...}' verify-real/run.ts
 */
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

function requireEnv(name: string, hint: string): string {
  const value = process.env[name];
  if (!value) {
    console.error(`Missing required environment variable ${name}. ${hint}`);
    process.exit(1);
  }
  return value;
}

const HOST = requireEnv('KWDB_HOST', 'Set it to the KWDB host, for example KWDB_HOST=db.example.com.');
const PORT = requireEnv('KWDB_PORT', 'Set it to the KWDB PostgreSQL-compatible port, for example KWDB_PORT=26257.');
const DB = requireEnv('KWDB_DATABASE', 'Set it to the database to run the verification against.');
const USER = requireEnv('KWDB_USER', 'Set it to a database user with read access.');
const PASSWORD = requireEnv('KWDB_PASSWORD', 'Set it to the password for that database user.');

const { cases, varSql } = JSON.parse(readFileSync(join(__dirname, 'cases.json'), 'utf8')) as {
  cases: Array<{ id: string; feature: string; expect: string; sql: string; expectFail?: boolean }>;
  varSql: Array<{ id: string; sql: string }>;
};

interface Result {
  id: string;
  feature: string;
  expect: string;
  status: 'OK' | 'FAIL' | 'EMPTY' | 'XFAIL';
  rows: number;
  first: string;
  error?: string;
  elapsedMs: number;
}

function run(id: string, feature: string, expect: string, sql: string): Result {
  if (!sql.trim()) {
    return { id, feature, expect, status: 'EMPTY', rows: 0, first: '', elapsedMs: 0 };
  }
  const started = Date.now();
  try {
    const out = execFileSync(
      'psql',
      [
        '-h',
        HOST,
        '-p',
        PORT,
        '-U',
        USER,
        '-d',
        DB,
        '-v',
        'ON_ERROR_STOP=1',
        '-Atq',
        '-F',
        '|',
        '-c',
        `SET statement_timeout='120s'; ${sql}`,
      ],
      {
        encoding: 'utf8',
        env: { ...process.env, PGPASSWORD: PASSWORD },
        stdio: ['ignore', 'pipe', 'pipe'],
        timeout: 180000,
        // A bare column in the GROUP BY multiplies the row count; the default
        // 1 MB maxBuffer aborts psql on those cases.
        maxBuffer: 256 * 1024 * 1024,
      }
    );
    const lines = out.split('\n').filter((l) => l.trim() !== '');
    return {
      id,
      feature,
      expect,
      status: 'OK',
      rows: lines.length,
      first: lines[0]?.slice(0, 240) ?? '',
      elapsedMs: Date.now() - started,
    };
  } catch (err) {
    const e = err as { stdout?: string; stderr?: string; message?: string };
    const msg = (e.stderr || e.stdout || e.message || '').split('\n').filter(Boolean).slice(0, 4).join(' | ');
    return {
      id,
      feature,
      expect,
      status: 'FAIL',
      rows: 0,
      first: '',
      error: msg.slice(0, 600),
      elapsedMs: Date.now() - started,
    };
  }
}

const results: Result[] = [];
for (const c of cases) {
  const r = run(c.id, c.feature, c.expect, c.sql);
  if (c.expectFail && r.status === 'FAIL') {
    r.status = 'XFAIL';
  }
  results.push(r);
}
for (const v of varSql) {
  results.push(run(v.id, 'variable-query-sql', 'executes', v.sql));
}

writeFileSync(join(__dirname, 'results.json'), JSON.stringify(results, null, 2));

const ok = results.filter((r) => r.status === 'OK');
const fail = results.filter((r) => r.status === 'FAIL');
const empty = results.filter((r) => r.status === 'EMPTY');
const xfail = results.filter((r) => r.status === 'XFAIL');

console.log(
  `\nTOTAL ${results.length}   OK ${ok.length}   FAIL ${fail.length}   EMPTY ${empty.length}   XFAIL(expected) ${xfail.length}\n`
);
for (const r of results) {
  const mark = r.status === 'OK' ? 'ok  ' : r.status === 'FAIL' ? 'FAIL' : r.status === 'XFAIL' ? 'xfail' : '----';
  const rows = r.status === 'OK' ? String(r.rows).padStart(6) : '     -';
  console.log(`${mark} ${r.id.padEnd(28)} ${rows} rows ${String(r.elapsedMs).padStart(6)}ms  ${r.feature}`);
  if (r.status === 'OK' && r.first) console.log(`       -> ${r.first}`);
  if (r.status === 'FAIL') console.log(`       !! ${r.error}`);
  if (r.status === 'XFAIL') console.log(`       ~~ expected failure: ${r.error}`);
}
console.log('');
if (fail.length) {
  console.log('FAILING IDS: ' + fail.map((f) => f.id).join(', '));
  process.exitCode = 1;
}
